package com.hfr.inventory.gui;
import com.hfr.packet.PacketDispatcher;import com.hfr.packet.wallart.WallArtConfigurePacket;import com.hfr.tileentity.TileEntityWallImage;import cpw.mods.fml.relauncher.Side;import cpw.mods.fml.relauncher.SideOnly;import net.minecraft.client.gui.*;import org.lwjgl.input.Keyboard;
@SideOnly(Side.CLIENT) public final class GuiWallArt extends GuiScreen{private final int dimension,x,y,z;private int width,height;private GuiTextField url;public GuiWallArt(TileEntityWallImage t){dimension=t.getWorldObj().provider.dimensionId;x=t.xCoord;y=t.yCoord;z=t.zCoord;width=t.getDisplayWidth();height=t.getDisplayHeight();}public void initGui(){Keyboard.enableRepeatEvents(true);url=new GuiTextField(fontRendererObj,this.width/2-120,this.height/2-35,240,20);url.setMaxStringLength(2048);url.setFocused(true);buttonList.add(new GuiButton(1,this.width/2-120,this.height/2,55,20,"W: "+width));buttonList.add(new GuiButton(2,this.width/2-60,this.height/2,55,20,"H: "+height));buttonList.add(new GuiButton(0,this.width/2+5,this.height/2,115,20,"Download"));}protected void actionPerformed(GuiButton b){if(b.id==1){width=width%5+1;b.displayString="W: "+width;}else if(b.id==2){height=height%5+1;b.displayString="H: "+height;}else if(b.id==0&&!url.getText().isEmpty()){PacketDispatcher.wrapper.sendToServer(new WallArtConfigurePacket(dimension,x,y,z,width,height,url.getText()));mc.displayGuiScreen(null);}}protected void keyTyped(char c,int k){if(k==Keyboard.KEY_ESCAPE){mc.displayGuiScreen(null);return;}url.textboxKeyTyped(c,k);}protected void mouseClicked(int x,int y,int b){super.mouseClicked(x,y,b);url.mouseClicked(x,y,b);}public void drawScreen(int mx,int my,float f){drawDefaultBackground();drawCenteredString(fontRendererObj,"Wall Art (HTTPS URL)",width/2,height/2-60,0xffffff);url.drawTextBox();super.drawScreen(mx,my,f);}public void onGuiClosed(){Keyboard.enableRepeatEvents(false);}}
